function shiftStructure(axis, index, count, insert) {
    var w = currentWb(), sheet = currentSheet();
    if (!w || !sheet) return;
    var delta = insert ? count : -count;
    pushUndo();
    var out = {};
    var keys = Object.keys(sheet.cells || {});
    for (var i = 0; i < keys.length; i++) {
      var rc = refRC(keys[i]);
      if (!rc) continue;
      var r = rc.r, c = rc.c;
      if (axis === 'row') {
        if (insert) { if (r >= index) r += count; }
        else { if (r >= index && r < index + count) continue; if (r >= index + count) r -= count; }
      } else {
        if (insert) { if (c >= index) c += count; }
        else { if (c >= index && c < index + count) continue; if (c >= index + count) c -= count; }
      }
      if (r < 0 || c < 0 || r >= ROW_COUNT || c >= MAX_COL) continue;
      out[coordName(r, c)] = sheet.cells[keys[i]];
    }
    for (var k in out) {
      if (!Object.prototype.hasOwnProperty.call(out, k)) continue;
      var v = out[k];
      if (typeof v === 'string' && v.charAt(0) === '=' && axis === 'row') {
        out[k] = shiftFormula(v, 'row', index, delta);
      } else if (typeof v === 'string' && v.charAt(0) === '=' && axis === 'col') {
        out[k] = shiftFormula(v, 'col', index, delta);
      }
    }
    sheet.cells = out;
    var list = sheet.validations || (sheet.validations = []);
    var kept = [];
    for (var j = 0; j < list.length; j++) {
      var ru = list[j];
      if (axis === 'row') {
        if (insert) {
          if (ru.r1 >= index) { ru.r1 += count; ru.r2 += count; }
        } else {
          if ((ru.r1 >= index && ru.r1 < index + count) || (ru.r2 >= index && ru.r2 < index + count)) continue;
          if (ru.r1 >= index + count) { ru.r1 -= count; ru.r2 -= count; }
        }
      } else {
        if (insert) {
          if (ru.c1 >= index) { ru.c1 += count; ru.c2 += count; }
        } else {
          if ((ru.c1 >= index && ru.c1 < index + count) || (ru.c2 >= index && ru.c2 < index + count)) continue;
          if (ru.c1 >= index + count) { ru.c1 -= count; ru.c2 -= count; }
        }
      }
      kept.push(ru);
    }
    sheet.validations = kept;
    ARC.save();
    ARC.render();
  }

function computePivot(w, pivot) {
    var src = null;
    for (var i = 0; i < w.sheets.length; i++) if (w.sheets[i].id === pivot.sourceSheet) src = w.sheets[i];
    if (!src) return { error: 'Pivot field is no longer available. Select a new field.' };
    var R = pivot.range;
    var vals = makeValues(src);
    var headers = [];
    for (var c = R.c1; c <= R.c2; c++) headers.push(vals(coordName(R.r1, c)).text);
    var ri = headers.indexOf(pivot.rows);
    var vi = headers.indexOf(pivot.values);
    var ci = pivot.columns ? headers.indexOf(pivot.columns) : -1;
    if (ri < 0 || vi < 0 || (pivot.columns && ci < 0)) {
      return { error: 'Pivot field is no longer available. Select a new field.' };
    }
    var method = pivot.summarize || 'SUM';
    var recs = [];
    for (var r = R.r1 + 1; r <= R.r2; r++) {
      recs.push({
        row: vals(coordName(r, R.c1 + ri)).text,
        col: pivot.columns ? vals(coordName(r, R.c1 + ci)).text : '',
        val: vals(coordName(r, R.c1 + vi)).text
      });
    }
    if (method !== 'COUNT') {
      var anyNum = false;
      for (var k = 0; k < recs.length; k++) {
        var tv = recs[k].val;
        if (tv !== '' && tv != null && !isNaN(Number(tv))) { anyNum = true; break; }
      }
      if (!anyNum) return { error: 'Value field requires numeric values' };
    }
    var rowKeys = [], colKeys = [];
    for (var a = 0; a < recs.length; a++) {
      if (rowKeys.indexOf(recs[a].row) < 0) rowKeys.push(recs[a].row);
      if (pivot.columns && colKeys.indexOf(recs[a].col) < 0) colKeys.push(recs[a].col);
    }
    function aggregate(rowKey, colKey) {
      var sum = 0, nums = 0, count = 0;
      for (var i2 = 0; i2 < recs.length; i2++) {
        var rec = recs[i2];
        if (rowKey !== null && rec.row !== rowKey) continue;
        if (colKey !== null && rec.col !== colKey) continue;
        var n = Number(rec.val);
        var ok = rec.val !== '' && rec.val != null && !isNaN(n);
        if (ok) { sum += n; nums++; }
        if (rec.val !== '' && rec.val != null) count++;
      }
      if (method === 'COUNT') return String(count);
      if (method === 'AVERAGE') return nums ? String(sum / nums) : '0';
      return String(sum);
    }
    var out = {};
    if (!pivot.columns) {
      out.A1 = pivot.rows;
      out.B1 = method + ' of ' + pivot.values;
      for (var x = 0; x < rowKeys.length; x++) {
        out[coordName(x + 1, 0)] = rowKeys[x];
        out[coordName(x + 1, 1)] = aggregate(rowKeys[x], null);
      }
      out[coordName(rowKeys.length + 1, 0)] = 'Grand Total';
      out[coordName(rowKeys.length + 1, 1)] = aggregate(null, null);
    } else {
      out.A1 = pivot.rows;
      for (var y = 0; y < colKeys.length; y++) out[coordName(0, y + 1)] = colKeys[y];
      out[coordName(0, colKeys.length + 1)] = 'Grand Total';
      for (var x2 = 0; x2 < rowKeys.length; x2++) {
        out[coordName(x2 + 1, 0)] = rowKeys[x2];
        for (var y2 = 0; y2 < colKeys.length; y2++) {
          out[coordName(x2 + 1, y2 + 1)] = aggregate(rowKeys[x2], colKeys[y2]);
        }
        out[coordName(x2 + 1, colKeys.length + 1)] = aggregate(rowKeys[x2], null);
      }
      var lr = rowKeys.length + 1;
      out[coordName(lr, 0)] = 'Grand Total';
      for (var y3 = 0; y3 < colKeys.length; y3++) out[coordName(lr, y3 + 1)] = aggregate(null, colKeys[y3]);
      out[coordName(lr, colKeys.length + 1)] = aggregate(null, null);
    }
    return { cells: out };
  }

function makeValues(sheet) {
    var cache = {}, stack = {};
    function get(key) {
      if (Object.prototype.hasOwnProperty.call(cache, key)) return cache[key];
      if (stack[key]) return { text: '#REF!', num: null, error: true };
      var raw = sheet.cells ? sheet.cells[key] : undefined;
      if (raw === undefined || raw === null || raw === '') return { text: '', num: null, empty: true };
      if (typeof raw === 'string' && raw.charAt(0) === '=') {
        stack[key] = true;
        var text;
        try { text = evaluateFormula(raw.slice(1), get); }
        catch (e) { text = (e && e.error) ? e.error : '#ERROR!'; }
        delete stack[key];
        var isErr = text.charAt(0) === '#';
        var num = (!isErr && text !== '' && !isNaN(Number(text))) ? Number(text) : null;
        var res = { text: text, num: num, error: isErr, formula: raw };
        cache[key] = res;
        return res;
      }
      var t = String(raw);
      var n2 = (t.trim() !== '' && !isNaN(Number(t))) ? Number(t) : null;
      return { text: t, num: n2 };
    }
    return get;
  }

function evaluateFormula(src, get) {
    var toks = tokenizeFormula(src);
    var p = 0;
    function peek() { return toks[p]; }
    function eat() { return toks[p++]; }
    function toNum(v) {
      if (typeof v === 'number') return v;
      if (v === null || v === undefined) return 0;
      if (typeof v === 'string') {
        if (v.charAt(0) === '#') throw errObj(v);
        var n = Number(v);
        if (v.trim() !== '' && !isNaN(n)) return n;
        throw errObj('#ERROR!');
      }
      if (Object.prototype.toString.call(v) === '[object Array]') {
        if (v.length === 1) return toNum(v[0]);
        throw errObj('#ERROR!');
      }
      throw errObj('#ERROR!');
    }
    function parseRefName(rf) {
      var m = /^\$?([A-Za-z]{1,3})\$?([0-9]+)$/.exec(rf);
      if (!m) return null;
      var c = COL_LIST.indexOf(m[1].toUpperCase());
      var r = parseInt(m[2], 10) - 1;
      if (c < 0 || r < 0) return null;
      return { r: r, c: c };
    }
    function cellValue(rf) {
      var w = get(rf);
      if (!w || w.empty) return null;
      if (w.error) throw errObj(w.text);
      return w.num !== null && w.num !== undefined ? w.num : w.text;
    }
    function rangeValues(a, b) {
      var A = parseRefName(a), B = parseRefName(b);
      if (!A || !B) throw errObj('#REF!');
      var out = [];
      for (var r = Math.min(A.r, B.r); r <= Math.max(A.r, B.r); r++) {
        for (var c = Math.min(A.c, B.c); c <= Math.max(A.c, B.c); c++) {
          out.push(cellValue(coordName(r, c)));
        }
      }
      return out;
    }
    function applyFn(name, args) {
      var flat = [];
      for (var i = 0; i < args.length; i++) {
        var a = args[i];
        if (Object.prototype.toString.call(a) === '[object Array]') {
          for (var j = 0; j < a.length; j++) flat.push(a[j]);
        } else flat.push(a);
      }
      var nums = [];
      for (var k = 0; k < flat.length; k++) {
        var v = flat[k];
        if (typeof v === 'number') { nums.push(v); continue; }
        if (typeof v === 'string' && v.trim() !== '' && !isNaN(Number(v)) && v.charAt(0) !== '#') nums.push(Number(v));
      }
      var total = 0;
      for (var s = 0; s < nums.length; s++) total += nums[s];
      if (name === 'SUM') return total;
      if (name === 'COUNT') return nums.length;
      if (name === 'AVERAGE') { if (!nums.length) throw errObj('#DIV/0!'); return total / nums.length; }
      if (name === 'MIN') return nums.length ? Math.min.apply(null, nums) : 0;
      if (name === 'MAX') return nums.length ? Math.max.apply(null, nums) : 0;
      throw errObj('#NAME?');
    }
    function parseExpr() {
      var v = parseTerm();
      for (;;) {
        var t = peek();
        if (t && t.t === '+') { eat(); v = toNum(v) + toNum(parseTerm()); }
        else if (t && t.t === '-') { eat(); v = toNum(v) - toNum(parseTerm()); }
        else return v;
      }
    }
    function parseTerm() {
      var v = parseUnary();
      for (;;) {
        var t = peek();
        if (t && t.t === '*') { eat(); v = toNum(v) * toNum(parseUnary()); }
        else if (t && t.t === '/') {
          eat();
          var d = toNum(parseUnary());
          if (d === 0) throw errObj('#DIV/0!');
          v = toNum(v) / d;
        } else return v;
      }
    }
    function parseUnary() {
      var t = peek();
      if (t && t.t === '-') { eat(); return -toNum(parseUnary()); }
      if (t && t.t === '+') { eat(); return parseUnary(); }
      return parsePrimary();
    }
    function parsePrimary() {
      var t = peek();
      if (!t) throw errObj('#ERROR!');
      if (t.t === 'num') { eat(); return t.v; }
      if (t.t === 'str') { eat(); return t.v; }
      if (t.t === 'err') { eat(); throw errObj(t.v); }
      if (t.t === '(') {
        eat();
        var v = parseExpr();
        var c = peek();
        if (!c || c.t !== ')') throw errObj('#ERROR!');
        eat();
        return v;
      }
      if (t.t === 'ref') {
        eat();
        var nx = peek();
        if (nx && nx.t === ':') {
          eat();
          var t2 = peek();
          if (!t2 || t2.t !== 'ref') throw errObj('#ERROR!');
          eat();
          return rangeValues(t.v, t2.v);
        }
        return cellValue(t.v);
      }
      if (t.t === 'name') {
        eat();
        var lp = peek();
        if (!lp || lp.t !== '(') throw errObj('#NAME?');
        eat();
        var args = [];
        if (peek() && peek().t === ')') { eat(); }
        else {
          for (;;) {
            args.push(parseExpr());
            var sep = peek();
            if (!sep) throw errObj('#ERROR!');
            if (sep.t === ',') { eat(); continue; }
            if (sep.t === ')') { eat(); break; }
            throw errObj('#ERROR!');
          }
        }
        return applyFn(t.v, args);
      }
      throw errObj('#ERROR!');
    }
    var out = parseExpr();
    if (p < toks.length) throw errObj('#ERROR!');
    if (typeof out === 'number') {
      if (!isFinite(out)) throw errObj('#DIV/0!');
      return String(Math.round(out * 1e10) / 1e10);
    }
    return String(out);
  }

function tokenizeFormula(src) {
    var t = [], i = 0;
    while (i < src.length) {
      var ch = src.charAt(i);
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') { i++; continue; }
      if (ch === '"') {
        var j = i + 1, s = '';
        while (j < src.length && src.charAt(j) !== '"') { s += src.charAt(j); j++; }
        if (j >= src.length) throw errObj('#ERROR!');
        t.push({ t: 'str', v: s }); i = j + 1; continue;
      }
      if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(src.charAt(i + 1)))) {
        var k = i;
        while (k < src.length && /[0-9.]/.test(src.charAt(k))) k++;
        var n = Number(src.slice(i, k));
        if (isNaN(n)) throw errObj('#ERROR!');
        t.push({ t: 'num', v: n }); i = k; continue;
      }
      if (/[A-Za-z_$]/.test(ch)) {
        var m = i;
        while (m < src.length && /[A-Za-z0-9_$]/.test(src.charAt(m))) m++;
        var w = src.slice(i, m); i = m;
        if (/^\$?[A-Za-z]{1,3}\$?[0-9]+$/.test(w)) t.push({ t: 'ref', v: w.toUpperCase().replace(/\$/g, '') });
        else if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(w)) t.push({ t: 'name', v: w.toUpperCase() });
        else throw errObj('#ERROR!');
        continue;
      }
      if (ch === '#') {
        var h = i + 1;
        while (h < src.length && /[A-Za-z0-9_/!]/.test(src.charAt(h))) h++;
        var lit = src.slice(i, h).toUpperCase();
        if (lit.charAt(lit.length - 1) !== '!') throw errObj('#ERROR!');
        t.push({ t: 'err', v: lit }); i = h; continue;
      }
      if ('+-*/()^:,='.indexOf(ch) >= 0) { t.push({ t: ch, v: ch }); i++; continue; }
      throw errObj('#ERROR!');
    }
    return t;
  }

function shiftFormula(formula, axis, index, delta) {
    var bad = false;
    var out = String(formula).replace(REF_RE, function (m, cAbs, col, rAbs, row) {
      var c = COL_LIST.indexOf(col.toUpperCase());
      var r = parseInt(row, 10) - 1;
      if (c < 0) return m;
      if (axis === 'row') {
        if (delta > 0) { if (r >= index) r += delta; }
        else { if (r === index) { bad = true; return '#REF!'; } if (r > index) r += delta; }
      } else {
        if (delta > 0) { if (c >= index) c += delta; }
        else { if (c === index) { bad = true; return '#REF!'; } if (c > index) c += delta; }
      }
      if (r < 0 || c < 0) { bad = true; return '#REF!'; }
      return cAbs + COL_LIST[c] + rAbs + (r + 1);
    });
    if (bad || out.indexOf('#REF!') >= 0) return '=#REF!';
    return out;
  }

function pushUndo() {
    var w = currentWb();
    if (!w) return;
    clearStatus();
    var ui = ARC.state.ui || (ARC.state.ui = {});
    var undo = ui.undo || (ui.undo = {});
    var redo = ui.redo || (ui.redo = {});
    if (!undo[w.id]) undo[w.id] = [];
    undo[w.id].push(JSON.parse(JSON.stringify(w)));
    if (undo[w.id].length > 40) undo[w.id].shift();
    redo[w.id] = [];
  }

function clearStatus() {
    var root = document.getElementById('status-root');
    if (root) { root.hidden = true; root.innerHTML = ''; }
    clearTimeout(ARC._statusTimer);
    ARC._undo = null;
  }

function currentWb() {
    var rt = ARC.route();
    if (rt.name !== 'workbook') return null;
    return getWb(rt.params[0]);
  }

function currentSheet() {
    var w = currentWb();
    if (!w || !w.sheets || !w.sheets.length) return null;
    for (var i = 0; i < w.sheets.length; i++) if (w.sheets[i].id === w.activeSheet) return w.sheets[i];
    return w.sheets[0];
  }

function getWb(id) {
    var list = ARC.state.workbooks || [];
    for (var i = 0; i < list.length; i++) if (String(list[i].id) === String(id)) return list[i];
    return null;
  }

function refRC(s) {
    var m = /^\$?([A-Za-z]{1,3})\$?([0-9]+)$/.exec(String(s));
    if (!m) return null;
    var c = COL_LIST.indexOf(m[1].toUpperCase());
    var r = parseInt(m[2], 10) - 1;
    if (c < 0 || r < 0) return null;
    return { r: r, c: c };
  }

function shiftStructure(axis, index, count, insert) {
    var w = currentWb(), sheet = currentSheet();
    if (!w || !sheet) return;
    var delta = insert ? count : -count;
    pushUndo();
    adjustPivotRanges(w, sheet.id, axis, index, count, insert);
    var out = {};
    var keys = Object.keys(sheet.cells || {});
    for (var i = 0; i < keys.length; i++) {
      var rc = refRC(keys[i]);
      if (!rc) continue;
      var r = rc.r, c = rc.c;
      if (axis === 'row') {
        if (insert) { if (r >= index) r += count; }
        else { if (r >= index && r < index + count) continue; if (r >= index + count) r -= count; }
      } else {
        if (insert) { if (c >= index) c += count; }
        else { if (c >= index && c < index + count) continue; if (c >= index + count) c -= count; }
      }
      if (r < 0 || c < 0 || r >= ROW_COUNT || c >= MAX_COL) continue;
      out[coordName(r, c)] = sheet.cells[keys[i]];
    }
    for (var k in out) {
      if (!Object.prototype.hasOwnProperty.call(out, k)) continue;
      var v = out[k];
      if (typeof v === 'string' && v.charAt(0) === '=' && axis === 'row') {
        out[k] = shiftFormula(v, 'row', index, delta);
      } else if (typeof v === 'string' && v.charAt(0) === '=' && axis === 'col') {
        out[k] = shiftFormula(v, 'col', index, delta);
      }
    }
    sheet.cells = out;
    var list = sheet.validations || (sheet.validations = []);
    var kept = [];
    for (var j = 0; j < list.length; j++) {
      var ru = list[j];
      if (axis === 'row') {
        if (insert) {
          if (ru.r1 >= index) { ru.r1 += count; ru.r2 += count; }
        } else {
          if ((ru.r1 >= index && ru.r1 < index + count) || (ru.r2 >= index && ru.r2 < index + count)) continue;
          if (ru.r1 >= index + count) { ru.r1 -= count; ru.r2 -= count; }
        }
      } else {
        if (insert) {
          if (ru.c1 >= index) { ru.c1 += count; ru.c2 += count; }
        } else {
          if ((ru.c1 >= index && ru.c1 < index + count) || (ru.c2 >= index && ru.c2 < index + count)) continue;
          if (ru.c1 >= index + count) { ru.c1 -= count; ru.c2 -= count; }
        }
      }
      kept.push(ru);
    }
    sheet.validations = kept;
    ARC.save();
    ARC.render();
  }

function computePivot(w, pivot) {
