    if (!src) return { error: 'Pivot field is no longer available. Select a new field.' };
    var R = pivot.range;
    if (!R || R.r2 < R.r1 || R.c2 < R.c1) {
      return { error: 'Pivot field is no longer available. Select a new field.' };
    }
