      throw errObj('#ERROR!');
    }
    function parseRefName(rf) {
      var m = /^\$?([A-Za-z]{1,3})\$?([0-9]+)$/.exec(rf);
      if (!m) return null;
      var c = COL_LIST.indexOf(m[1].toUpperCase());
      var r = parseInt(m[2], 10) - 1;
      if (c < 0 || r < 0 || r >= ROW_COUNT || c >= MAX_COL) return null;
      return { r: r, c: c };
